function short(n, u) { u=0; n=int(n<0?0:n); while(n>=1000 && u<5) { n=int(n/1000); u++ } return sprintf("%d%s", n%10000, u?substr(" KMGTP",u+1,1):"") }
/^body\.(response\.)?usage\./ && $2 ~ /^[0-9]+$/ { k=$1; sub(/:$/,"",k); sub(/^.*\./,"",k); v[k]=$2; seen=1 }
END {
  if(!seen) exit
  input=v["input_tokens"]; out=v["output_tokens"]; cached=v["cached_tokens"]; written=v["cache_write_tokens"]; thinking=v["reasoning_tokens"]
  hit=input>0?int(cached*100/input):0; b=int(hit*7/100); if(b<0)b=0; if(b>6)b=6
  split("▁ ▂ ▃ ▄ ▅ ▆ ▇",blocks," ")
  printf "::stats::✥%s%s%s::%d in, %d cached (%d%%)", short(out), (cached>0?blocks[b+1]:"_"), short(input), input, cached, hit
  if(written>0) printf ", %d written",written
  printf ", %d out",out
  if(thinking>0) printf " (%d thinking)",thinking
  printf "\n"
}
